 "content": "from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            components.append(cells)
    target = min(components, key=lambda cells: sum(grid[r][c] == 9 for r, c in cells))
    for r, c in target:
        out[r][c] = 0
    return out
